                    }

                    return Err(InsertError::conflict(&route, prefix, current));
                }

                return current.insert_child(prefix, &route, val);
            }

            // Otherwise add value to current node
            if current.value.is_some() {
                return Err(InsertError::conflict(&route, prefix, current));
            }

            current.value = Some(UnsafeCell::new(val));

            return Ok(());
        }
    }

