fn join_paths(a: &str, b: &str) -> String {
    if a.is_empty() {
        return b.to_owned();
    }

    if b.is_empty() {
        return a.to_owned();
    }

    let a = a.trim_end_matches('/');
    let b = b.trim_start_matches('/');

    if a.is_empty() {
        format!("/{}", b)
    } else if b.is_empty() {
        a.to_owned()
    } else {
        format!("{}/{}", a, b)
    }
}

